import{_ as t,o as r,c as e,a5 as d}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"本书路线图","description":"用一张六部结构表和三條阅读路径说明《人生进阶指南》的阅读顺序、每一步留下的东西，以及容量很小时怎样开始。","frontmatter":{"title":"本书路线图","description":"用一张六部结构表和三條阅读路径说明《人生进阶指南》的阅读顺序、每一步留下的东西，以及容量很小时怎样开始。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-0/roadmap.md","filePath":"threads/part-0/roadmap.md","lastUpdated":1795392000000}'),i={name:"threads/part-0/roadmap.md"};function l(o,a,h,p,n,s){return r(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="本书路线图" tabindex="-1">本书路线图 <a class="header-anchor" href="#本书路线图" aria-label="Permalink to &quot;本书路线图&quot;">​</a></h1><p>这本书从一个普通人的失败与恢复写起，再走向重新学习、AI 协作、日常实践和长期行动。它不要求你按顺序走完，但值得先知道整张地图长什么样。</p><h2 id="全书结构" tabindex="-1">全书结构 <a class="header-anchor" href="#全书结构" aria-label="Permalink to &quot;全书结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>这一部追问什么</th><th>入口</th></tr></thead><tbody><tr><td>序章与开卷</td><td>我为什么愿意重新开始？这本书准备给我什么？</td><td><a href="./prologue">序章</a> · <a href="./reader-guide">如何读这本书</a></td></tr><tr><td>第一部：把自己放回生活</td><td>失败、身体、关系与事业失去秩序时，怎样先接住自己？</td><td><a href="./../part-2/return-to-life">本部导语</a> · <a href="./../part-2/my-story">我的故事</a></td></tr><tr><td>第二部：重新学习，打开输入</td><td>恢复之后，怎样用一件具体的事重新训练注意力和能力？</td><td><a href="./../part-1/open-input">本部导语</a> · <a href="./../part-1/0-cefr">CEFR 自测</a></td></tr><tr><td>第三部：借工具放大能力</td><td>怎样使用 AI，又不把判断、隐私和责任一起交出去？</td><td><a href="./../part-3/amplify-ability">本部导语</a> · <a href="./../part-3/1-ai-learning">使用 AI 学习一切</a></td></tr><tr><td>第四部：实践与恢复</td><td>怎样让学习回到身体、家庭和日常，并在中断后回来？</td><td><a href="./../part-4/practice-and-recovery">本部导语</a> · <a href="./../part-4/week-1">第一周实践</a></td></tr><tr><td>第五部：行动与长期改变</td><td>怎样把一轮练习变成真实作品，并让九十天以后仍有回声？</td><td><a href="./../part-5/long-term-action">本部导语</a> · <a href="./../part-5/90-day-plan">九十天行动篇</a></td></tr><tr><td>第六部：与自己做终身朋友</td><td>怎样了解、善待、提升自己，并长期相处？</td><td><a href="./../part-6/1-understanding-yourself">了解自己</a> · <a href="./../part-6/afterword">后记</a></td></tr></tbody></table><p>目录名 <code>part-2</code>、<code>part-1</code> 等是历史主题标识，<strong>不是阅读顺序</strong>。书的顺序以这张表和目录为准：先第一部（故事与恢复），再第二部（重新学习）。</p><h2 id="三条阅读路径" tabindex="-1">三条阅读路径 <a class="header-anchor" href="#三条阅读路径" aria-label="Permalink to &quot;三条阅读路径&quot;">​</a></h2><h3 id="故事优先" tabindex="-1">故事优先 <a class="header-anchor" href="#故事优先" aria-label="Permalink to &quot;故事优先&quot;">​</a></h3><p>适合此刻更想被理解、而不是先学方法的人。</p><ol><li><a href="./prologue">序章</a> → <a href="./../part-2/my-story">我的故事</a>；</li><li><a href="./../part-2/depression-anxiety-recovery">我还在这里</a> → <a href="./../part-2/recovery">恢复篇</a>；</li><li><a href="./../part-2/decision">选择篇</a> → <a href="./../part-2/relationships">关系篇</a>；</li><li>有余力时再进入<a href="./../part-1/open-input">第二部导语</a>。</li></ol><h3 id="方法优先" tabindex="-1">方法优先 <a class="header-anchor" href="#方法优先" aria-label="Permalink to &quot;方法优先&quot;">​</a></h3><p>适合带着一个具体任务来、想尽快开始的人。</p><ol><li><a href="./../part-1/0-cefr">CEFR 自测</a> → <a href="./../part-1/1-understanding">认知与训练原则</a>；</li><li>在词汇、语法、听、读、说、写中选<strong>一条</strong>主线，做完一次十四天实验；</li><li><a href="./../part-3/1-ai-learning">使用 AI 学习一切</a> → <a href="./../part-3/4-artifacts-and-delivery">作品篇</a>；</li><li><a href="./../part-4/week-1">第一周实践</a> → <a href="./../part-5/90-day-plan">九十天行动篇</a>。</li></ol><h3 id="容量很小的时候" tabindex="-1">容量很小的时候 <a class="header-anchor" href="#容量很小的时候" aria-label="Permalink to &quot;容量很小的时候&quot;">​</a></h3><p>适合身体或情绪状态不允许长时间阅读的人。</p><ol><li>只读<a href="./../part-2/recovery">恢复篇</a>里“降低负荷”的一节，不做练习；</li><li>打开<a href="./../../templates/learning-state">学习状态模板</a>，只写四行：问题、线索、最小动作、边界；</li><li>今天到此为止。把<a href="./../../templates/rhythm-ledger">节律账本</a>放到明天或下周，不补作业。</li></ol><p>三条路径可以中途交换。读故事读到想做事，就转到方法；做方法做到无力，就回到恢复。书的结构允许往返。</p><h2 id="今天只有五分钟" tabindex="-1">今天只有五分钟 <a class="header-anchor" href="#今天只有五分钟" aria-label="Permalink to &quot;今天只有五分钟&quot;">​</a></h2><p>如果你现在只有一个很小的空档，不要试图开始一部书：</p><ol><li>打开<a href="./../../templates/learning-state">学习状态模板</a>；</li><li>写下你眼前最真实的一个问题；</li><li>写下一个<strong>今天能完成</strong>的最小动作；</li><li>写下一个必须守住的边界（隐私、身体、关系或金钱）。</li></ol><p>这四行就是一次开始。五分钟不需要产出结论，只需要把下一步从雾里拿出来。</p><h2 id="读完以后" tabindex="-1">读完以后 <a class="header-anchor" href="#读完以后" aria-label="Permalink to &quot;读完以后&quot;">​</a></h2><p>正文之后是附录，按用途排列：先查<a href="./../../reference/glossary">术语与方法索引</a>，再按问题进入<a href="./../../reference/reading-map">阅读地图</a>；需要动手时打开<a href="./../../templates/toolkit">工具箱总览</a>；想引用或核对来源时看<a href="./../../reference/bibliography">参考文献</a>与<a href="./../../reference/sources-and-citation">资料、引用与核验说明</a>；想了解这本书是怎样被做出来的，可以读附录里的<a href="./../part-5/book-as-proof">本书案例</a>。</p><p>如果你读完了，最值得留下的不是“我读完了”，而是一次真实交付、一份复测记录，或一个愿意在九十天后回来检查的决定。把它们放进<a href="./../../templates/90-day-cycle">九十日行动总表</a>。</p>',23)])])}const m=t(i,[["render",l]]);export{c as __pageData,m as default};
